      end.setDate(end.getDate() + (6 - dayOfWeek));
      return {
        start: start.toISOString().split('T')[0],
        end: end.toISOString().split('T')[0],
      };
    } else {
      // monthly
      start.setDate(1);
      end.setMonth(end.getMonth() + 1);
      end.setDate(0);
      return {
        start: start.toISOString().split('T')[0],
        end: end.toISOString().split('T')[0],
      };
    }
  };

  const loadTasks = async () => {
    try {
      const { start, end } = getDateRange();
      const tasksData = await plannerApi.getItems({
        date_start: start,
        date_end: end,
        view_type: viewType
      });
      setTasks(tasksData);

      const linksMap: Record<string, Note[]> = {};
      for (const task of tasksData) {
        try {
          const linkedNotes = await plannerApi.getLinks(task.id);
          linksMap[task.id] = linkedNotes;
        } catch {
          linksMap[task.id] = [];
        }
      }
      setTaskLinkedNotes(linksMap);
    } catch (error) {
      showSnackbar('Failed to load tasks', 'error');
    }
  };

  const loadNoteActivities = async () => {
    try {
      const { start, end } = getDateRange();
      const startDate = new Date(start);
      const endDate = new Date(end);
      const activitiesMap: Record<string, DayActivities> = {};

      for (let d = new Date(startDate); d <= endDate; d.setDate(d.getDate() + 1)) {
        const dateStr = d.toISOString().split('T')[0];
        try {
          const activities = await notesApi.getActivitiesByDate(dateStr);
          activitiesMap[dateStr] = activities;
        } catch {
          activitiesMap[dateStr] = { date: dateStr, created: [], updated: [], moved: [] };
        }
      }

      setNoteActivities(activitiesMap);
    } catch (error) {
      showSnackbar('Failed to load note activities', 'error');
    }
  };

  const handleCreateTask = async (task: CreatePlannerItemRequest) => {
    try {
      if (editTask) {
        await plannerApi.update(editTask.id, task);
        showSnackbar('Task updated', 'success');
      } else {
        await plannerApi.create(task);
        showSnackbar('Task created', 'success');
      }
      setEditTask(null);
      loadTasks();
    } catch (error) {
      showSnackbar('Failed to save task', 'error');
    }
  };

  const handleToggleComplete = async (id: string) => {
    try {
      await plannerApi.toggleComplete(id);
      loadTasks();
    } catch (error) {
      showSnackbar('Failed to toggle task', 'error');
    }
  };

  const handleDeleteTask = async (id: string) => {
    try {
      await plannerApi.delete(id);
      showSnackbar('Task deleted', 'success');
      loadTasks();
    } catch (error) {
      showSnackbar('Failed to delete task', 'error');
    }
  };

  const handleEditTask = (task: PlannerItem) => {
    setEditTask(task);
    setDialogOpen(true);
  };

  const navigateDate = (direction: 'prev' | 'next' | 'today') => {
    const newDate = new Date(currentDate);

    if (direction === 'today') {
      setCurrentDate(new Date());
      return;
    }

    const delta = direction === 'prev' ? -1 : 1;

    if (viewType === 'weekly') {
      newDate.setDate(newDate.getDate() + (delta * 7));
    } else {
      // monthly
      newDate.setMonth(newDate.getMonth() + delta);
    }

    setCurrentDate(newDate);
  };

  const getDisplayDate = () => {
    if (viewType === 'weekly') {
      const { start, end } = getDateRange();
      return `${new Date(start).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} - ${new Date(end).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}`;
    } else {
      // monthly
      return currentDate.toLocaleDateString('en-US', { year: 'numeric', month: 'long' });
    }
  };

  const groupTasksByDate = () => {
    const grouped: { [date: string]: PlannerItem[] } = {};
    tasks.forEach(task => {
      if (!grouped[task.date]) {
        grouped[task.date] = [];
      }
      grouped[task.date].push(task);
    });
    return grouped;
  };

  const getWeekDays = () => {
    const { start } = getDateRange();
    const days = [];
    // Parse the date string properly to avoid timezone issues
    const [year, month, day] = start.split('-').map(Number);
    const startDate = new Date(year, month - 1, day);

    for (let i = 0; i < 7; i++) {
      const currentDay = new Date(startDate);
      currentDay.setDate(startDate.getDate() + i);
      days.push(currentDay);
    }
    return days;
  };

  const isToday = (date: Date) => {
    const today = new Date();
    return date.toDateString() === today.toDateString();
  };

  const getMonthCalendar = () => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    // First day of month
    const firstDay = new Date(year, month, 1);
    // Last day of month
    const lastDay = new Date(year, month + 1, 0);

    // Start from Sunday of the first week
    const startDate = new Date(firstDay);
    startDate.setDate(startDate.getDate() - startDate.getDay());

    // Build 6 weeks (42 days) to cover all possible month layouts
    const calendar: Date[][] = [];
    let currentWeek: Date[] = [];

    for (let i = 0; i < 42; i++) {
      const day = new Date(startDate);
      day.setDate(startDate.getDate() + i);
      currentWeek.push(day);

      if (currentWeek.length === 7) {
        calendar.push(currentWeek);
        currentWeek = [];
      }
    }

    return calendar;
  };

  const handleDayClick = (dateStr: string) => {
