                      onClick={() => handleDayClick(dateStr)}
                    >
                      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <Typography 
                          variant="body2" 
                          fontWeight={today ? 600 : 400}
                          color={today ? 'primary' : isCurrentMonth ? 'text.primary' : 'text.secondary'}
                        >
                          {day.getDate()}
                        </Typography>
                        {noteCount > 0 && (
                          <Box
                            sx={{
                              bgcolor: 'secondary.main',
                              color: 'white',
                              borderRadius: '10px',
                              px: 0.75,
                              py: 0.125,
                              fontSize: '0.65rem',
                              fontWeight: 600,
                            }}
                          >
                            {noteCount}
                          </Box>
                        )}
                      </Box>
                      <Box sx={{ mt: 0.5, display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                        {dayTasks.slice(0, 3).map(task => (
                          <Typography
                            key={task.id}
                            variant="caption"
                            sx={{
                              overflow: 'hidden',
                              textOverflow: 'ellipsis',
                              whiteSpace: 'nowrap',
                              textDecoration: task.status === 'completed' ? 'line-through' : 'none',
                              color: task.status === 'completed' ? 'text.disabled' : 'text.primary',
                            }}
                          >
                            {task.title}
                          </Typography>
                        ))}
                        {dayTasks.length > 3 && (
                          <Typography variant="caption" color="text.secondary">
                            +{dayTasks.length - 3} more
                          </Typography>
                        )}
                      </Box>
                    </Box>
                  );
                })}
              </Box>
            ))}
          </Box>
        )}
      </Box>

      <Fab
        color="primary"
        sx={{ position: 'fixed', bottom: 16, right: 16 }}
        onClick={() => {
          setEditTask(null);
          setDialogOpen(true);
        }}
      >
        <AddIcon />
      </Fab>

      <CreateTaskDialog
        open={dialogOpen}
        onClose={() => {
          setDialogOpen(false);
          setEditTask(null);
        }}
        onSave={handleCreateTask}
        editTask={editTask}
      />

      <DayViewModal
        open={dayViewModalOpen}
        onClose={() => setDayViewModalOpen(false)}
        date={selectedDayDate}
        tasks={groupedTasks[selectedDayDate] || []}
        activities={noteActivities[selectedDayDate]}
        onNavigateToNote={onNavigateToNote}
        onToggleComplete={handleToggleComplete}
        onDeleteTask={handleDeleteTask}
        onEditTask={handleEditTask}
        taskLinkedNotes={taskLinkedNotes}
      />

      <Snackbar
        open={snackbar.open}
        autoHideDuration={3000}
        onClose={() => setSnackbar({ ...snackbar, open: false })}
      >
        <Alert severity={snackbar.severity}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

